'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const N = input[idx++];
const K = input[idx++];
const T = input[idx++];

const plates = input.slice(idx, idx + N);
idx += N;
const group = input.slice(idx, idx + N);

const useGroup = K <= N - K;
const initial = [];
for (let i = 0; i < N; i++) {
  if ((group[i] === 1) === useGroup) initial.push(i + 1);
}

const M = initial.length;
const width = 9 * M + 1;
const INF = 1e9;
const dp = new Int32Array((M + 1) * width);
dp.fill(INF);
dp[0] = 0;

for (let i = 0; i < N; i++) {
  const maxSelected = Math.min(M, i + 1);
  const value = plates[i];
  const position = i + 1;

  for (let j = maxSelected; j >= 1; j--) {
    const srcBase = (j - 1) * width;
    const dstBase = j * width + value;
    const moveCost = Math.abs(position - initial[j - 1]);
    const maxScore = 9 * (j - 1);

    for (let score = 0; score <= maxScore; score++) {
      const cost = dp[srcBase + score];
      if (cost !== INF) {
        const newCost = cost + moveCost;
        const target = dstBase + score;
        if (newCost < dp[target]) dp[target] = newCost;
      }
    }
  }
}

let answer;
const finalBase = M * width;

if (useGroup) {
  answer = 0;
  for (let score = 0; score < width; score++) {
    if (dp[finalBase + score] <= T) answer = score;
  }
} else {
  const total = plates.reduce((sum, value) => sum + value, 0);
  let minimumOmitted = 0;
  while (minimumOmitted < width && dp[finalBase + minimumOmitted] > T) {
    minimumOmitted++;
  }
  answer = total - minimumOmitted;
}

console.log(answer);
